$avatar = sfConfig::get('base_simad').'/images/simad/ico_logo_users.png';
echo javascript_tag("               
  function canClose(cad,id,opc) {
    var xselect2 = parent.jQuery('#$campoText').data('select2');
    //***************************************************************************
    if(opc == '0'){
      parent.document.form1.$campoText.value = cad;    
      parent.document.form1.$campoId.value = id;
      var preload_data = [{id: id, text: cad, img: '$avatar'}];
      //*************************************************************************
      try{      
          parent.jQuery('#$campoText').select2('data', preload_data).trigger('change');
      }catch(err) {
          console.log(err.message);
      }
    }
    if(opc == '1'){
      var ustext = parent.jQuery('#$campoText').val().split(',');
      var idold = parent.jQuery('#$campoId').val().split(',');
      //*************************************************************************
      idold = jQuery.grep(idold, function(n){ return (n); });        
      ustext = jQuery.grep(ustext, function(n){ return (n); });
      //*************************************************************************
      ustext.push(cad);
      idold.push(id);
      //*************************************************************************
      try{
        if(xselect2 != null){
          var preload_data = [{id: id, text: cad, img: '$avatar'}];
          var data_load = parent.jQuery('#$campoText').select2('data');
          parent.jQuery('#$campoText').select2('data', data_load.concat(preload_data)).trigger('change');
        }else{
          parent.jQuery('#$campoId').val(idold.join(','));
          parent.jQuery('#$campoText').val(ustext.join(','));
        }
      }catch(err) {
        console.log(err.message);
      }
    }
    parent.jQuery.CloseModalSIMAD();
  } 
") ?>
